      expect(into(analysis, 'details', 3).tier).toBe('newPeak');
      expect(into(analysis, 'details', 3).change).toBe(-10);
      expect(into(analysis, 'details', 1).tier).toBe('first');
      expect(into(analysis, 'details', 1).newHardest).toBe(false);
